import codecs,json,sys,unicodedata
rows=json.load(sys.stdin)
result=[]
for row in rows:
    data=bytes(row['input'])
    scenarios=[]
    for split in range(len(data)+1):
        decoder=codecs.getincrementaldecoder(row['encoding'])(row['errors'])
        events=[]
        for chunk,final in ((data[:split],False),(data[split:],True)):
            try:
                event={'text':list(map(ord,decoder.decode(chunk,final)))}
            except UnicodeDecodeError as error:
                event={'error':[error.encoding,list(error.object),error.start,error.end,error.reason]}
            pending,flag=decoder.getstate()
            event['state']=[list(pending),flag]
            events.append(event)
        scenarios.append(events)
    result.append(dict(encoding=row['encoding'],errors=row['errors'],input=row['input'],scenarios=scenarios))
print(json.dumps(dict(oracle=dict(version=sys.version,unicode=unicodedata.unidata_version,byteorder=sys.byteorder),rows=result)))
